import type { ComponentProps, ReactNode } from "react";
import { Button } from "./button";
import { cn } from "./utils";

type ContextReferenceKind = string;

type ContextReference = {
    id: string;
    kind: ContextReferenceKind;
    label: string;
    kindLabel?: string;
    description?: string;
    included?: boolean;
    disabled?: boolean;
    thumbnailUrl?: string;
};

type ContextTrayProps = Omit<
    ComponentProps<"section">,
    "aria-label" | "children"
> & {
    label?: string;
    items: readonly ContextReference[];
    loading?: boolean;
    error?: ReactNode;
    emptyMessage?: string;
    onIncludedChange?: (
        item: ContextReference,
        included: boolean,
    ) => void;
    onOpen?: (item: ContextReference) => void;
    onRemove?: (item: ContextReference) => void;
};

const knownKindLabels: Record<string, string> = {
    file: "파일",
    folder: "폴더",
    image: "이미지",
    document: "문서",
    selection: "선택 영역",
    person: "사람",
    custom: "사용자 정의",
};

function getKindLabel(item: ContextReference) {
    if (item.kindLabel?.trim()) return item.kindLabel.trim();
    const knownLabel = knownKindLabels[item.kind.toLowerCase()];
    if (knownLabel) return knownLabel;
    const words = item.kind.replace(/[_-]+/g, " ").trim();
    return words ? words[0].toUpperCase() + words.slice(1) : "Reference";
}

function getSafeThumbnailUrl(value: string | undefined) {
    const candidate = value?.trim();
    if (!candidate || /[\u0000-\u001f\u007f]/.test(candidate)) return null;

    try {
        const parsed = new URL(candidate, "https://ui.invalid");
        if (parsed.protocol === "https:" || parsed.protocol === "http:" ||
            parsed.protocol === "blob:") {
            return candidate;
        }
    } catch {
        return null;
    }
    return null;
}

function validateContextItems(items: readonly ContextReference[]) {
    if (!Array.isArray(items)) {
        throw new TypeError("ContextTray items must be an array.");
    }

    const ids = new Set<string>();
    for (const item of items) {
        if (!item || typeof item !== "object" ||
            typeof item.id !== "string" || !item.id.trim() ||
            typeof item.kind !== "string" || !item.kind.trim() ||
            typeof item.label !== "string" || !item.label.trim() ||
            ids.has(item.id)) {
            throw new Error(
                "ContextTray items need unique IDs, kinds and labels.",
            );
        }
        if (item.included !== undefined &&
            typeof item.included !== "boolean") {
            throw new TypeError(
                "ContextTray item inclusion state must be boolean.",
            );
        }
        if (item.disabled !== undefined &&
            typeof item.disabled !== "boolean") {
            throw new TypeError(
                "ContextTray item disabled state must be boolean.",
            );
        }
        for (const [name, value] of [
            ["kindLabel", item.kindLabel],
            ["description", item.description],
            ["thumbnailUrl", item.thumbnailUrl],
        ] as const) {
            if (value !== undefined &&
                (typeof value !== "string" || !value.trim())) {
                throw new TypeError(
                    `ContextTray item ${name} must be a non-empty string when provided.`,
                );
            }
        }
        ids.add(item.id);
    }
}

function ContextTray({
    label = "컨텍스트 항목",
    items,
    loading = false,
    error,
    emptyMessage = "추가된 컨텍스트 항목이 없습니다.",
    onIncludedChange,
    onOpen,
    onRemove,
    className,
    ...props
}: ContextTrayProps) {
    if (!label.trim()) throw new Error("ContextTray requires a label.");
    if (!emptyMessage.trim()) {
        throw new Error("ContextTray emptyMessage cannot be blank.");
    }
    if (typeof loading !== "boolean") {
        throw new TypeError("ContextTray loading must be boolean.");
    }
    validateContextItems(items);

    return (
        <section aria-label={label} data-ui="context-tray"
            data-state={error != null ? "error" : loading ? "loading" :
                items.length === 0 ? "empty" : "ready"}
            className={cn("min-w-0 text-foreground", className)} {...props}>
            {error != null ? (
                <p role="alert" className="m-0 text-sm text-danger">
                    {error || "컨텍스트 항목을 불러오지 못했습니다."}
                </p>
            ) : loading ? (
                <p role="status" aria-live="polite"
                    className="m-0 text-sm text-muted">
                    컨텍스트 항목을 불러오는 중입니다…
                </p>
            ) : items.length === 0 ? (
                <p role="status" className="m-0 text-sm text-muted">
                    {emptyMessage}
                </p>
            ) : (
                <ul aria-label={label}
                    className="m-0 grid list-none gap-2 p-0">
                    {items.map((item) => {
                        const thumbnailUrl = getSafeThumbnailUrl(
                            item.thumbnailUrl,
                        );
                        const disabled = item.disabled === true;

                        return (
                            <li key={item.id}
                                className="flex min-w-0 items-start gap-2">
                                <input type="checkbox"
                                    checked={item.included ?? true}
                                    disabled={disabled || !onIncludedChange}
                                    aria-label={`${item.label} 포함`}
                                    onChange={(event) =>
                                        onIncludedChange?.(
                                            item,
                                            event.currentTarget.checked,
                                        )
                                    }
                                    className="mt-1 size-4 shrink-0 accent-accent focus-visible:outline-2 focus-visible:outline-focus" />
                                {thumbnailUrl && (
                                    <img src={thumbnailUrl} alt=""
                                        aria-hidden="true"
                                        className="size-9 shrink-0 rounded-sm object-cover" />
                                )}
                                <div className="min-w-0 flex-1">
                                    <div className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
                                        <span className="min-w-0 break-words text-sm font-medium">
                                            {item.label}
                                        </span>
                                        <span className="shrink-0 text-xs text-muted">
                                            {getKindLabel(item)}
                                        </span>
                                    </div>
                                    {item.description && (
                                        <p className="m-0 mt-0.5 break-words text-xs text-muted">
                                            {item.description}
                                        </p>
                                    )}
                                </div>
                                {(onOpen || onRemove) && (
                                    <div className="flex shrink-0 gap-1">
                                        {onOpen && (
                                            <Button type="button"
                                                variant="ghost" size="icon"
                                                aria-label={`${item.label} 열기`}
                                                disabled={disabled}
                                                onClick={() => onOpen(item)}>
                                                <span aria-hidden="true">↗</span>
                                            </Button>
                                        )}
                                        {onRemove && (
                                            <Button type="button"
                                                variant="ghost" size="icon"
                                                aria-label={`${item.label} 제거`}
                                                disabled={disabled}
                                                onClick={() => onRemove(item)}>
                                                <span aria-hidden="true">×</span>
                                            </Button>
                                        )}
                                    </div>
                                )}
                            </li>
                        );
                    })}
                </ul>
            )}
        </section>
    );
}

export { ContextTray };
export type { ContextReference, ContextReferenceKind, ContextTrayProps };
